		render_tab_still = "Picture", render_tab_anim = "Animation", render_go_anim = "Render animation",
		render_no_anim = "The scene has no animation yet",
		render_ssao = "Ambient occlusion (SSAO, experimental)", render_ssao_radius = "SSAO radius, units", render_ssao_strength = "SSAO strength", render_ssao_passes = "SSAO passes (renders)", render_ssao_passes_tip = "As in SFM's progressive render: the occlusion is taken this many times, each time with the directions turned another way, and averaged — the finished frame has no noise. The preview and the viewport take up to 4. 1 = one pass.",
		render_ssao_tip = "Soft contact shadows in corners, folds and under objects, as in SFM. The editor's own effect: no other addon is needed. Seen in the preview, the render, the video and the Render look of the viewport. Experimental: dark halos, stripes or flicker may appear — turn it off if the frame looks wrong.",
		render_engine_tip = "The picture is rendered by the game's own renderer through the chosen camera, with every enabled post-processing addon (standard GMod effects, Workshop shaders, shaders built on GShader Library), then taken from the screen. Limits: the resolution is not higher than the screen, 2× smoothing is not applied. Depth of field (b0.2.6) takes one engine frame for every pass of the lens, so it renders slower.",
		render_engine_size = "source: %d × %d px of the screen",
		shaders_addons_note = "Every post-processing effect registered in the game: standard GMod ones and those from addons and the Workshop. Tick an effect and tune it on the right — it is the effect's own panel, the same as in the Q menu. These effects draw themselves in the game's main frame, so they reach the preview and the render only in Engine frame mode.",
		shaders_col_on = "On",
		shaders_col_effect = "Effect",
