		keys_reset_all = "Reset all keys", keys_reset_q = "Return all keys to their defaults?",
		keys_g_list = "Object list (with the cursor over it)", keys_list_select_all = "Select all objects",
		keys_list_copy = "Copy objects", keys_list_paste = "Paste objects", edit_select_all = "Select all",
		help_list_keys = "Object list (cursor over it): select all / copy / paste objects",
		obj_selected_all = "Selected: %d (locked and hidden ones are left out)", obj_copied = "Objects copied: %d",
		obj_clip_empty = "Nothing copied: select objects and press Ctrl + C over the object list",
		obj_clip_gone = "The copied objects are not in the scene any more",
		-- b0.2.2
		cam_znear = "Near clip plane", view_znear = "Near clip plane of the work camera", view_znear_n = "%g units",
		cam_tip_znear = "What is closer to the lens than this many units is cut away. Make it smaller to bring the camera right up to a face or a hand; very small values may make far surfaces flicker.",
		poster_title = "Poster (progressive render)",
		poster_size_scene = "Render size of the scene",
		poster_side = "Long side",
		poster_passes = "passes",
		poster_start = "Start",
		poster_stop = "Stop",
		poster_save = "Save",
		poster_autosave = "Save when done",
		poster_hint = "Start: the picture is refined pass by pass, as in SFM (depth of field, soft shadows, smoothing)",
		poster_progress = "%d x %d  ·  pass %d of %d",
		poster_stopped = "stopped",
		poster_finished = "done",
		poster_size_now = "Poster %d x %d",
		poster_done_note = "Poster %d x %d, %d passes",
		light_kelvin_k = "Temperature, K",
		ctl_vfov = "Beam height",
		ctl_tip_vfov = "The vertical angle of the beam, apart from its width (as SFM's vertical field of view): a wide, low strip of light. 0 — as high as it is wide.",
		cam_focus_on = "Focus on",
		cam_focus_none = "nothing (the Render window's focus)",
		cam_focus_tip = "Keep the focus of the depth of field on an object (as in SFM): it stays sharp wherever it goes, what is in front and behind blurs. Click to pick the object.",
		cam_focus_dist = "Focal distance", cam_aperture = "Aperture", cam_dof_on = "Depth of field of this camera",
		cam_focus_dist_tip = "How far from the lens the picture is sharp, units (SFM: focalDistance). While you change it the views show the plane in focus: through this camera what is behind it turns lilac inside a square (as in SFM) and the distance is shown under the frame. Changing it turns the camera's depth of field on (Render - Camera effects).",
		cam_aperture_tip = "How strongly what is off the focal distance blurs (SFM: aperture, default 0.2). Bigger - a shallower sharp zone; above 0.4 the frame is already very soft. Drag: steps of 0.1, Shift - 0.01; the mouse wheel steps it too.",
		cam_focus_pick = "Pick focus (click)", cam_focus_pick_tip = "As SFM's Set Camera Focal Distance: the next click in the Primary Viewport puts the focal plane of this camera on what is under the cursor (a face, a hand, a prop). The wheel over Focal distance fine-tunes it, Shift - finer.",
		cam_focus_pick_hint = "Click what should be in focus in the Primary Viewport",
		cam_sec_ao = "Ambient occlusion",
		cam_ao = "Occlusion",
		cam_ao_scene = "as the scene",
		cam_ao_on = "own",
		cam_ao_off = "off",
		cam_ao_tip = "Soft contact shadows (SSAO, SFM's) for this camera — in its view in the viewports and in its renders. Click to switch.",
		cam_aoradius = "AO radius",
		cam_aostrength = "AO strength",
		cam_tip_aoradius = "SFM's SSAORadius: the occlusion looks around a surface up to a quarter of this, units (SFM's default 15). Changing it gives the camera its own occlusion.",
		cam_tip_aostrength = "SFM's SSAOStrength: how deep behind a surface an occluder still counts, times the radius (SFM's default 1). Bigger - darker and wider.",
		cam_aobias = "AO bias",
		cam_tip_aobias = "SFM's SSAOBias: the start point off the surface, a part of its distance from the camera (SFM's default 0.0005). Bigger - fewer dark spots on flat surfaces, less contact.",
		cam_tonemap = "Tone map scale", cam_tonemap_tip = "SFM's toneMapScale: brightness of this camera's picture (1 - as is). Changing it turns the camera's exposure on (Render - Camera effects).",
		cam_bloom = "Bloom scale", cam_bloom_tip = "SFM's bloomScale: how much of a blurred copy of the frame is added - the bright parts glow (SFM's default 0.28, 0 - none).",
		cam_bloomwidth = "Bloom width", cam_bloomwidth_tip = "SFM's bloomWidth: how wide the glow spreads, pixels of a 720-line frame (SFM's default 9).",
		view_vp_ao = "Ambient occlusion in viewports",
		view_vp_ao_0 = "Off",
		view_vp_ao_1 = "Through cameras",
		view_vp_ao_2 = "Always (also the work camera)",
		about_p1 = "Much faster playback of scenes with shooting: while the game's own particles (tracers, shells, sparks, muzzle flashes, dust of hits) are alive, the Primary Viewport is drawn in the place of the main game frame instead of besides it — one view of the map a frame instead of two (a recorded shoot-out on gm_scrapland: 44 ms a frame → 11 ms). The Secondary Viewport set to «when the scene changes» draws 8 pictures a second while something moves, not every frame.",
		about_p2 = "The near clip plane is now set: a camera's own (Animation Set Editor, beside the lens) and the work camera's (View → Near clip plane of the work camera); 3 units by default instead of 4, so a camera can come closer to a face before it is cut away.",
		about_p4 = "The whole source code of GM:FM is open on GitHub under the MIT license (the GitHub button above): fork it, change it, build your own version. Changes from other developers may get into the Workshop version, always credited — message the author on Steam.",
		about_p3 = "Fixed: the Render button grey and dead after a look at the Animation tab of a scene without animation (until the editor was opened again); the render preview and SSAO broken on game builds without the R32F texture format («bad argument #8 to 'GetRenderTargetEx'»).",
		-- b0.2.3
		keys_snap = "Snap the gizmo to steps (hold while dragging)", view_snap = "Snapping (hold %s while dragging)",
		view_snap_move = "Move: %g units", view_snap_rot = "Turn: %g°", view_snap_scale = "Scale: %g",
		view_snap_always = "Snap always (hold %s for a free move)",
		reset_rotation = "Reset rotation", hist_reset_rotation = "reset rotation",
		env_sound = "Sound of the map", env_mute_map = "Mute the map's own sounds",
		env_mute_map_note = "Wind, birds, machinery and other looping sounds of the map go quiet, for a clean sound track. Saved with the scene.",
		props_face = "Face", props_flexscale = "Expression scale",
		props_flexscale_hint = "As the Face Poser's flex scale: every face slider goes this many times further (goofy faces of TF2 models).",
		about_u1 = "Material changes are keyed now: the material of the whole model and of each slot, the colours of the slots and the stretching (length, width, height) switch or move at keys, like the skin — before, one change showed over the whole timeline.",
		about_u2 = "Snapping: hold Ctrl while dragging the gizmo and the move goes in steps of 8 units, the turn in 15°, the scale in 0.1 (View → Snapping sets the steps, the key can be changed in Interface settings → Keys). Reset rotation: Edit menu and the object menu → Utilities.",
		about_u3 = "Environment → Sound of the map: mute the map's own looping sounds (wind, birds, machinery) for a clean sound track, saved with the scene. Object properties → Face → Expression scale: the Face Poser's flex scale for every face slider (goofy faces of TF2 models).",
		about_u4 = "Simplified Chinese (简体中文) — the translation by fugui9527121, thank you! Help → Interface language.",
		about_u5 = "Fixed: the actor of a gameplay take falling as a limp ragdoll when another take was recorded with Physics of the scene on; a menu of the menu bar that did not close on a click in the viewport.",
		-- b0.2.4
		about_w1 = "Saved looks: Material presets keep the materials of a model, of its slots and their colours under a name and put them on any object (right click in the Animation Set Editor, or Object properties → Material); Outfits keep what a character wears and dress another one in it at once (right click on the character → Outfits).",
		about_w2 = "Break into pieces: a crate, a barrel, a melon falls apart at the playhead as when it breaks in the game — the pieces appear in its place and fall with a physics take (right click → Utilities).",
		about_w3 = "Animation render: a sequence of PNG or JPEG pictures, one a frame, with the sound as .wav (Video file); the depth of field is in videos now — the camera's own or the Render window's; the Secondary Viewport and the render preview move smoothly while the game has frames to spare.",
		about_w4 = "Fixed: a closed Primary Viewport that would not come back (Windows and the layouts did nothing); attached lights, cameras and effects trailing behind a moving parent; the glow of a light lost behind effects and see-through props; the keys (Ctrl+Z, Space…) dead after typing into the search field.",
		about_x1 = "Attaching: a knife or a gun stays exactly in the hand while the arm moves and in the video (it drifted out of the drawn hand); attached to a hand it is far from, the object is put into that hand (left or right); objects can be attached to cameras and lights; attaching is keyed: a prop lies on the table until the key where it was put into the hand and leaves it at the key where it was let go.",
		about_x2 = "Bone keys as in SFM: every bone with keys of its own gets a row under the selected character; a key of a bone can have its own motion (Stepped, Linear…) even when other bones are keyed at the same frame; with Bone keys on, a key of the whole character leaves the bones that have keys of their own alone.",
		about_x3 = "IK: View → keep the feet planted and keep the hands planted are separate switches (move the pelvis — the feet stay, and the hands too if you want). Gizmo after Blender and SFM: rings turn as the mouse goes round the centre (no jumps when a ring is seen edge-on), an axis pointing at the camera moves with the mouse; snapping steps 10 units, 30°, 0.1 and View → Snapping → Snap always (Ctrl — free move).",
		about_x4 = "View → Unlock slider limits (as SFM's flex unlocker): face, light and camera sliders go past their ends, e.g. a face slider at 2.5 or -1. Worn heads, masks and clothes with face sliders follow the wearer's face and can be posed themselves. Lip sync of the TF2 mercenaries for animation (HWM models) uses the game's own phonemes of each class, and their faces are no longer crooked at rest (their sliders go from -1 to 1).",
		about_x5 = "Gameplay takes record vehicles: the game's cars and boats and those of simfphys, Glide, LVS, with their wheels and suspension. Animation import: Forward, units/s for walks made in place. Ready motions no longer freeze the editor on long animations (dances).",
		about_x6 = "Timeline: Left / Right arrows step through frames, a scroll bar under the tracks. Secondary Viewport: its own aspect ratio (gear → Aspect ratio). Hide a bone (right click on it): not shown and not picked by a click. A camera at a character's eyes shows its body without the head (a camera close to a character no longer makes it vanish); the camera of a recorded take is true first person — the player's own body is not drawn, as in the game.",
		about_x7 = "Fixed: more than a few lights on a map shone through walls — up to 8 lights cast shadows now (the game's limit), the Shadows tab says how many have none; WebM that the game cannot create is written as AVI instead of failing.",
		about_y1 = "First-person takes with the gun in front of the eyes: the view model (the weapon with the hands, every bone of its animation) is recorded with the take, hangs on the take's camera and is drawn in its view as the game draws it — with its own field of view and never inside a wall. Each weapon held gets its own model, shown while it was in the hands.",
		about_y2 = "Vehicles in takes: the rider sits as Glide bends it (leaning on a motorbike, feet on the pegs, hands on the bars) instead of upright through the bike; fast motion no longer shakes (the keys of a take are put on whole frames exactly); the engine is in the take — Glide's engine layers with their revs and the looped sounds of addons (wheels, wind) become clips with a volume and pitch line.",
		about_y3 = "Sound through the Web Audio API (as Glide plays its engines): clips start exactly, volume, pan and speed glide without clicks, MP3 and OGG now go into the sound track of a video, and lip sync measures MP3 / OGG voices at once. gmfm_webaudio 0 goes back to the game's BASS. Up to 1500 sound clips; bursts of the EFT weapons for ARC9 are recorded shot by shot (they were merged into one clip as a 'loop').",
		about_y4 = "Fixed: the TF2 mercenaries (HWM) taken from the Q menu had a crooked face and lip sync kept it in every key — such faces are put at rest, also in saved scenes; a selection box in the object list takes the rows scrolled past with the wheel; an object held in a hand no longer jumps aside at every touch of the gizmo on some characters; the only bone of a prop (static_prop) selects the whole prop; the work camera brought into a character no longer cuts its head off; guests of a server in the GM:FM gamemode are no longer asked over and over and shown 'no permission'.",
		about_y5 = "From SFM: ambient occlusion is seen in the viewports while you work (View → Ambient occlusion in viewports: through cameras / always), and every camera has its own (Animation Set Editor → the camera → Ambient occlusion: as the scene, on with its own radius and strength, off); a camera keeps its focus on an object (Focus on) — it stays sharp wherever it goes, the rest blurs; lights: the height of the beam apart from its width, any colour temperature by kelvins, wider ranges of intensity and distance.",
		about_y6 = "Shift + F4 leaves the editor whatever holds it (in the GM:FM gamemode it asks first). A render cannot be broken off: Esc and the console stay closed while a video or a picture is shot. A scene without a camera is rendered through the work camera. The video's sound decodes every file through Web Audio — WAV of any kind, MP3, OGG. Clear the scene also clears the NPC marks of a take. First-person takes: the camera is in the player's eyes as in the game, not in the model's bobbing head.",
		about_y7 = "Videos render several times faster, as in SFM: a frame is shot in the very game frame the scene arrives in, the server answers without waiting ticks, the engine frame is ordered at once, particle effects take 4 game frames a frame instead of 8 and an effect on a moving weapon no longer waits 0.2 s every frame (a scene with 22 effects: 31 s for 48 frames before, 13 s now). While a video renders the editor is not drawn: one window shows the last frame, the progress, the frames a second and the time left, and stops the render (Hide the editor while rendering).",
		about_y8 = "From SFM: Render -> Animation -> Quality - Draft, Normal, High, Final set the passes of every frame and the JPEG level at once; the smoothing of a video takes its part of the passes too. File -> Poster: a still refined pass by pass, watched as it grows and saved as PNG or JPEG; smoothing by samples shifted by a part of a pixel, as SFM does, instead of a frame of twice the size.",
		about_y9 = "The timeline has SFM's three editors - the buttons at its left end, F2 / F3 / F4. Clip Editor: the shots on a film strip with their start and length, the FX clips and the sounds under Picture and Sound. Motion Editor: the keys of the objects, the time selection in SFM's green. Graph Editor: the curves of the selected object or bone, its channels listed on the left (a click shows or hides one, a double click shows it alone) - it was a separate window.",
		about_y10 = "Camera focus as in SFM: Focal distance and Aperture right in the Animation Set Editor; while you change them the views show the plane in focus - through the camera everything behind it turns pink and the distance is written under the frame. The model browser's preview as SFM's: a floor grid and the tabs Render (wireframe, collision model, no ground, lock view, look at camera), Sequences, Activities and Skins; the skin picked there goes into the scene with the model. A new effect in a scene with animation plays from the playhead to the end (Effects window: Play in the animation) instead of hanging frozen in the air.",
		about_y11 = "Fixed (Workshop): on maps with area portal windows (gm_boreas: the dome) the views showed the void and out-of-bounds places when the camera was far from the player's body - the game shut those windows by the distance from the body, not from the camera. While the editor is open they stay open, and get the map's own distances back when it closes.",
		about_y12 = "Takes from demos, as HLAE does (asked on the Workshop): record a demo with File -> Demos -> Record a demo and play it from Esc -> Demos (no console needed) - the GM:FM bar at the top records what it shows - players with their weapons, NPCs, ragdolls, moving props, the view, the sounds - at any speed of the demo. In a game on the same map File -> Import demo take turns it into the scene: ragdolls keyed along it and a camera of the view, so lights, cameras and the SFM render of GM:FM go over a match from any server. gmfm_demo shows the bar; it records a live game too.",
		about_y13 = "Fixed (Workshop: 65 GB of RAM and a crash while rendering with shader addons): the check of a render target could fail on some computers or under the render state of another addon, and then a new full-size target was made every two seconds for good - the game never frees them; now a target is replaced twice at most and the check switches itself off where it cannot be trusted. The addon effects keyed with a camera are no longer switched on and off at every frame of a render (an addon that builds its buffers when switched on built them every frame). The render look and the occlusion of the viewports change their size in steps of 64 pixels, not with every pixel of a dragged splitter.",
		about_y14 = "A Free frame no longer shows less than 16:9: it has the shape of the Primary Viewport, often a wide strip with the timeline under it, and with the field of view being the horizontal one such a strip cut off the top and the bottom of the scene. A free frame wider than 16:9 now keeps the height of a 16:9 frame and shows more at the sides (Hor+, as games do on wide screens); the viewports, the render, the preview, picking and the camera frustum all go by it. 16:9, narrower free frames and the fixed aspects are as before.",
		about_y15 = "Fixed: a video rendered with Engine frame was smeared sideways in every frame - the game's own motion blur (Options - Video) took the jump between the work camera and the render's camera for a fast turn; it is off while the editor is open (the renders blur motion themselves). Fixed: with ambient occlusion on, the preview and the render showed dark copies of objects beside them (a car and a soldier 'drawn' on a wall) - the viewports' occlusion, worked out at another size, was laid on the render's passes as well.",
		about_y16 = "Cameras as in SFM. Ambient occlusion is SFM's own now, its math read out of SFM: SSAORadius, SSAOStrength (how deep the occluders reach) and SSAOBias with SFM's defaults 15, 1, 0.0005, a new noise in every pass, SFM's blur. A camera can have its own (Animation Set Editor or Render - Camera effects), and toneMapScale, bloomScale and bloomWidth (SFM's bloom: a blurred copy of the frame added in linear light). Depth of field is a real lens as in SFM: the whole focal plane is sharp, not only the middle of the frame, and with depth of field every pass takes the occlusion of its own view (no sharp dark outlines around blurred things).",
		about_y17 = "The Clip Editor of the timeline (F2) only shows, as in SFM: no gizmo, and the Primary Viewport is the render's picture that refines while nothing moves. The Motion (F3) and Graph (F4) editors show the quick, grainier picture and move things.",
		about_y18 = "As in SFM: the focus is the camera's Focal distance only, set by hand and keyed - the 'Focus on' object is gone. The plane in focus is shown as SFM shows it: a lilac square in the middle of the camera's view (what is behind it tinted, the distance under the frame) and its outline at the end of the camera's frustum in the other views. A viewport through a camera shows the camera's bloom (bloomScale) at once. Holding Left / Right (or , / .) runs the playhead on, faster and faster. First-person takes: the gun and the hands are seen only through the take's own camera (in other views they hung beside the body as long thin sticks), the body of a custom model is never in its own eyes' view, and the hands are taken as the game drew them, on the gun (they hung beside it while walking; older takes are drawn glued to the gun).",
		about_y19 = "Focus made easier, as asked: Aperture moves in steps of 0.1 from 0 to 2 (Shift - 0.01, the mouse wheel too; SFM's default 0.2 - above 0.4 the frame is already very soft); Focal distance has most of its slider for the near distances and the wheel fine-tunes it; Pick focus (click) puts the focal plane on what you click in the viewport, as SFM's Set Camera Focal Distance; the lilac square has one size in the world, so you see it come nearer and go away. How to use is updated with new pictures: cameras and focus, SFM camera settings, bloom, ambient occlusion, Clip / Motion / Graph editors, quality presets and the progress window, the poster, first-person takes and demos.",
		about_y20 = "Depth of field works with Engine frame too: the engine shoots the frame once for every pass of the lens (the camera moved over the aperture), each shot is cut out shifted so that the focal plane stays in place, and they are averaged - the picture, the video and the Render window preview (it refines pass by pass). It takes one game frame per pass, so such a render is slower.",
		about_y21 = "Reference video: Windows → Reference video plays a clip beside the editor. Put .webm or .mov (H.264) files into data/speditor/refs/ and pick one in the list; the window also copies the folder path for you.",
		about_y22 = "Several bones at once: Shift or Ctrl + click a bone on the skeleton or in the bone tree adds it to the selection. The gizmo moves, turns and scales them together (bones without physics), and a key holds them all. Fingers can be posed in one go.",
		about_y23 = "Rotator on one bone: Turn only this bone makes just the selected bone turn round its own origin (a wheel, a screw, a track link) instead of the whole object.",
		about_y24 = "Attach to any bone: the Attach menu lists every bone, including the fingers and hair of a ragdoll and the bones of a model without physics (SFM, TF2 characters). The place is kept as the bone is drawn on the screen.",
		about_y25 = "Fixes from the reports: a drag of a hand or an arm keys every bone it moved (bones of an IK chain were lost before); while the editor is open the map area portals stay open, so the inside of gm_boreas no longer shows the void.",
		about_y26 = "Random face: the face presets have Random. A physics take tells how many selected objects have no physics to fall with (models without physics, attached objects) and leaves them out.",
		about_tab_info = "About", about_tab_news = "What's new",
		about_news_hint = "Every update of GM:FM since b0.1, the newest first.",
		-- the news of older versions for the What's new tab (b0.2.4: kept from their releases)
		about_v021_1 = "The GM:FM gamemode, a film studio of its own (not Sandbox: no spawn menu, context menu or tool gun): start a game with the gamemode GM:FM on any map — the editor opens at once and stays open; the player, walking around the scene and gameplay takes still work. A start window after Source Filmmaker's: a new scene, the saved scenes, a gameplay take, another map. File → Change map instead of Exit Editor. In Sandbox the editor is what it was.",
		about_v021_2 = "Gameplay takes: the weapons are chosen before the take (always in the gamemode, an option in Sandbox) — Done gives them and starts the countdown; also the length of the countdown, a time limit, full health and armour, god mode and ammunition.",
		about_v021_3 = "Fixed: the render preview and the render black with ambient occlusion (SSAO) on — Source Filmmaker's occlusion, film grain and colour correction now run at DirectX level 90 too (the Linux build); a map's own fog (gm_scrapland) no longer breaks the occlusion or the fog of the Environment window.",
		about_v021_4 = "Fixed: hotkeys (Ctrl + Z, Ctrl + Y, Space…) that stopped at random until the editor was opened again; the Render button doing nothing until the map was reloaded (a lost frame of a render no longer hangs it); the Free aspect ratio taking the whole screen (16:9) while the Primary Viewport was hidden.",
		about_v021_5 = "NPCs of a take: pick NPCs from the spawn menu list and put each where it should stand by a click in the viewport (the wheel turns it), with its weapon and its attitude to you; they appear on their marks when the take starts, and their AI can wait for the recording itself. From SFM: Up / Down jump to the previous / next key, Shift + , / . by half a second, Ctrl + , / . to the bookmarks; View → Auto aim the work camera; Edit → Select objects no camera sees.",
		about_v01_1 = "Record gameplay: Camera of the take — First person (a camera strictly in your character's eyes, looking where you aimed, even if the game showed you from behind) or Third person (no camera of the player). A second take numbers its copies: <nick> view (rec) 2, w_smg1 2…",
		about_v01_2 = "Weapon effects of a take come out of the gun: the muzzle flash, the shell and the tracer are fired from the muzzle of the weapon in the hand (they used to hang half a body lower).",
		about_v01_3 = "Tracks on the timeline, like the track groups of SFM's clip editor: put objects under a named track that folds into one row with all their keys (right click a row → Track). The Film (shots) row splits, trims and speeds up shots; the timeline goes before frame 0 and past the end.",
		about_v01_4 = "Previews, as in SFM: the Model browser shows the model under the cursor turning in its idle animation; the Effects browser plays the chosen particle system over and over. Particles of Workshop addons are grouped by addon, subfolders included.",
		about_v01_5 = "The motion path in the viewport shows the real way an object goes — the arcs of continuous keys, the jumps of Hold keys. New guide: How to use → A good animation, step by step (blocking, splining, timing, overlap, walking, shooting).",
		about_v01_6 = "The render shows only the cameras of the scene, never the work camera. The player shows animations without depth of field; a video keeps the camera's own keyed depth of field with all of its passes (Render → Animation → Depth of field of the camera).",
		about_v01_7 = "Gizmo and bones are picked exactly where they are drawn (the viewport picture was 3% larger and shifted); the hovered axis and bone are highlighted. A rig with IK controls (R), IK chains of your own, physics on / off for ragdolls.",
		about_v01_8 = "Fullbright makes props and characters flat too; SSAO works in the player; the C and Q menus are blocked in the editor; a timecode h:mm:ss:ff on the viewport.",
		about_v01_9 = "New interface themes: HL2 Media Player, GMod Classic, Aero Blur. The interface scale also scales the rows of the object lists.",
		about_v01_10 = "Help → Self-test grew to 38 steps: renders in extreme settings measured by their pixels, cameras, many objects and their limits, animation edits, every theme, scale and language. A render target that stops taking drawing is replaced on the fly.",
		about_v01_11 = "SPeditor is now GM:FM — Garry's Mod Filmmaker, in beta: not only posters, but animation and film. Console commands are gmfm_* (the old speditor_* / saeditor_* still work, your settings are taken over).",
		about_v01_12 = "Eyes can be animated: the eye target goes into the keys and moves between them. Element Viewer → eyes: look at the camera / look ahead. Noise (as in Blender) in Procedural motion: a random shake of an object, a camera or single bones.",
		about_v01_13 = "Gizmo and rig size and line width (View → Gizmo size / Rig size, Settings → Look), the rings of the head can be hidden. The gizmo is drawn over the picture: it shows in the render look, with fullbright and with addons that stopped it.",
		about_v01_14 = "Fixed: characters black in fullbright on some maps; particles of a take (bullet smoke, sparks) hanging in the air for good; the look of an object lost with addons that wrap SetSubMaterial (Advanced Colour Tool).",
		about_v01_15 = "Addon effects in camera keys: Render window → Addon effects in keys takes the Q-menu post-processing (and GShader effects) into a scene camera; they are keyed with it and blend between keys — a depth of field or a colour change over a shot (Engine frame).",
		about_v01_16 = "Fixed: a ragdoll posed outside the editor (physgun, Ragdoll Mover) jumped back to its old pose when the editor opened; the bones of a worn object (Wear) could not be edited — now they can, also the ones it shares with the character. PAC3 outfits and SSAO are marked experimental.",
