		fx_shader_none = "Материалы шейдеров не найдены. Установите аддон с шейдерами или положите набор в папку шейдеров («Окна» → «Шейдеры аддонов» → «Папка шейдеров»).",
		fx_shader_missing = "Материал шейдера не найден: %s",
		fx_shader_buffers = "Этот шейдер читает буферы движка (глубину, нормали). Они есть только у основного кадра игры, поэтому используйте его вместе с режимом «Кадр движка».",
		about_f1 = "Рабочее место как в SFM: окна стыкуются встык, вкладки вытягиваются в отдельные окна, раскладки сохраняются и восстанавливаются. Любое окно можно держать поверх остальных: правый щелчок по полосе вкладок → «Свойства окна» → «Поверх всех окон» (у браузера моделей включено по умолчанию).",
		about_f2 = "Основной и дополнительный вьюпорты с рамкой кадра, направляющими композиции (трети, золотое сечение, центр, безопасные зоны) и фиксированной экспозицией.",
		about_f11 = "Свет: точечные источники и прожекторы с цветом, дальностью и яркостью, готовые пресеты и трёхточечная схема вокруг выбранной модели. У прожекторов — мягкие тени со своей мягкостью края, смещениями глубины и наклона и ближней границей, настраиваемое затухание, параллельный луч «как от солнца» и маски света.",
		about_f12 = "Вкладка «Тени»: качество карты теней, сколько источников отбрасывают тени и до какого расстояния от камеры, общий множитель мягкости; тени пропов от света карты — включение, подробные или пятнами, сколько их рисуется, длина, цвет и направление.",
		about_f13 = "Эффекты камер сцены (у рабочей камеры их нет): «рыбий глаз», виньетка, тоновые кривые для RGB и каждого канала, HDR, свечение (bloom), резкость, контуры, Toy Town, текстуризация, оверлей и до трёх своих шейдеров. Настраиваются в окне «Рендер», видны в его предпросмотре и в итоговом рендере; вьюпорты остаются чистыми.",
		about_f14 = "Шейдеры из мастерской и аддонов. В режиме «Кадр движка» картинку рисует сам движок игры, поэтому аддоны пост-обработки — в том числе шейдеры на GShader Library — попадают в предпросмотр и итоговый рендер. В окне «Шейдеры аддонов» перечислены все зарегистрированные эффекты, у каждого своя панель настроек.",
		about_f15 = "Папка шейдеров: положите скачанный набор (materials и shaders/fxc) в addons/speditor/shaders и нажмите «Пересканировать» — он подключится без перезапуска игры, а его шейдеры появятся в списке «Свой шейдер».",
		about_f16 = "Множественное выделение (Shift или Ctrl + щелчок): перемещение, поворот, масштаб, дублирование и удаление сразу нескольких объектов.",
		about_f17 = "Библиотека поз и сцены: сохранение, загрузка, автосохранение с несколькими копиями; сцена помнит камеру, настройки кадра, свойства объектов, настройки света и эффекты камер.",
		about_f18 = "Рендер в PNG или JPEG до 3840 px во внеэкранный буфер: сглаживание, глубина резкости, полная яркость и большой живой предпросмотр, который масштабируется вместе с окном «Рендер».",
		about_f19 = "Отмена и повтор для каждой правки.",
		about_f20 = "Уведомления редактора: сохранения, автосохранения, рендеры, ошибки и подсказки появляются карточками в углу экрана, в стиле интерфейса. Журнал сообщений, звук и время показа — в «Окна» → «Уведомления».",
		about_f21 = "Темы интерфейса: GM:FM UI, копия стандартного скина GMod, встроенные скины и свои из папки themes. Редактор использует только свои скины, поэтому интерфейсы из мастерской его не ломают; смена темы не сбрасывает полную яркость, открытые окна и выбранную камеру.",
		about_f22 = "Интерфейс на русском и английском.",
