		cam_tonemap = "Tone map scale", cam_tonemap_tip = "toneMapScale из SFM: яркость картинки этой камеры (1 - как есть). Изменение включает экспозицию камеры (Рендер - Эффекты камеры).",
		cam_bloom = "Bloom scale", cam_bloom_tip = "bloomScale из SFM: сколько размытой копии кадра добавляется - яркие места светятся (в SFM по умолчанию 0.28, 0 - нет).",
		cam_bloomwidth = "Bloom width", cam_bloomwidth_tip = "bloomWidth из SFM: как широко расходится свечение, пикселей кадра высотой 720 строк (в SFM по умолчанию 9).",
		view_vp_ao = "Объёмные тени во вьюпортах",
		view_vp_ao_0 = "Выкл.",
		view_vp_ao_1 = "Через камеры",
		view_vp_ao_2 = "Всегда (и рабочая камера)",
		about_p1 = "Намного быстрее проигрываются сцены со стрельбой: пока живут частицы самой игры (трассеры, гильзы, искры, вспышки выстрелов, пыль от попаданий), основной вьюпорт рисуется вместо главного кадра игры, а не вдобавок к нему — один вид карты за кадр вместо двух (записанная перестрелка на gm_scrapland: 44 мс на кадр → 11 мс). Второй вьюпорт в режиме «при изменении сцены» рисует 8 картинок в секунду, пока что-то движется, а не каждый кадр.",
		about_p2 = "Ближняя плоскость отсечения теперь настраивается: своя у камеры (редактор набора анимации, рядом с объективом) и у рабочей камеры («Вид» → «Ближняя плоскость рабочей камеры»); по умолчанию 3 единицы вместо 4, камеру можно поднести ближе к лицу, прежде чем его срежет.",
		about_p4 = "Весь исходный код GM:FM открыт на GitHub под лицензией MIT (кнопка GitHub выше): делайте форки, меняйте, собирайте свою версию. Изменения других разработчиков могут попасть в версию мастерской, всегда с упоминанием авторов — пишите автору в Steam.",
		about_p3 = "Исправлено: кнопка «Рендер» серая и не работает после взгляда на вкладку «Анимация» в сцене без анимации (до перезахода в редактор); превью рендера и SSAO не работали в сборках игры без формата текстур R32F («bad argument #8 to 'GetRenderTargetEx'»).",
		-- b0.2.3
		keys_snap = "Шаги гизмо — привязка (удерживать при перетаскивании)", view_snap = "Привязка (держите %s при перетаскивании)",
		view_snap_move = "Сдвиг: %g ед.", view_snap_rot = "Поворот: %g°", view_snap_scale = "Масштаб: %g",
		view_snap_always = "Шагами всегда (%s — свободно)",
		reset_rotation = "Сбросить поворот", hist_reset_rotation = "сброс поворота",
		env_sound = "Звук карты", env_mute_map = "Выключить звуки самой карты",
		env_mute_map_note = "Ветер, птицы, механизмы и другие зацикленные звуки карты замолкают — для чистой звуковой дорожки. Сохраняется со сценой.",
		props_face = "Лицо", props_flexscale = "Масштаб выражений",
		props_flexscale_hint = "Как flex scale в Face Poser: каждый ползунок лица заходит во столько раз дальше (смешные лица моделей TF2).",
		about_u1 = "Изменения материала теперь в ключах: материал всей модели и каждого слота, цвета слотов и растяжение (длина, ширина, высота) переключаются или плавно меняются на ключах, как скин, — раньше одно изменение было видно на всём таймлайне.",
		about_u2 = "Привязка: держите Ctrl, перетаскивая гизмо, — сдвиг идёт шагами по 8 единиц, поворот по 15°, масштаб по 0,1 (шаги — «Вид» → «Привязка», клавиша меняется в настройках интерфейса → «Клавиши»). «Сбросить поворот»: меню «Правка» и меню объекта → «Утилиты».",
		about_u3 = "«Окружение» → «Звук карты»: выключить зацикленные звуки самой карты (ветер, птицы, механизмы) ради чистой звуковой дорожки, сохраняется со сценой. Свойства объекта → «Лицо» → «Масштаб выражений»: flex scale из Face Poser для всех ползунков лица (смешные лица моделей TF2).",
		about_u4 = "Упрощённый китайский (简体中文) — перевод fugui9527121, спасибо! «Справка» → «Язык интерфейса».",
		about_u5 = "Исправлено: актёр записи игры падал обмякшим рэгдоллом, когда записывался следующий дубль с включённой «Физикой сцены»; меню из полосы меню не закрывалось кликом во вьюпорте.",
		-- b0.2.4
		about_w1 = "Сохранённый вид: пресеты материалов хранят под именем материалы модели, её слотов и их цвета и накладывают их на любой объект (правый клик в редакторе набора анимации или «Свойства объекта» → «Материал»); наряды хранят то, что надето на персонаже, и сразу одевают в это другого (правый клик по персонажу → «Наряды»).",
		about_w2 = "Разбить на обломки: ящик, бочка, арбуз разваливаются на текущем кадре, как при поломке в игре, — обломки появляются на месте и падают в записи физики (правый клик → «Утилиты»).",
		about_w3 = "Рендер анимации: последовательность картинок PNG или JPEG, по одной на кадр, со звуком в .wav («Видеофайл»); глубина резкости теперь есть в видео — своя у камеры или из окна «Рендер»; дополнительный вьюпорт и превью рендера движутся плавно, пока у игры есть запас кадров.",
		about_w4 = "Исправлено: закрытый основной вьюпорт не возвращался («Окна» и раскладки ничего не делали); прикреплённые свет, камеры и эффекты отставали от движущегося родителя; свечение света пропадало за эффектами и полупрозрачными пропами; клавиши (Ctrl+Z, пробел…) не работали после ввода в поле поиска.",
		about_x1 = "Привязка: нож или оружие держатся точно в руке, когда рука двигается, и в видео (раньше «уплывали» из нарисованной руки); привязанный к далёкой руке предмет сам переносится в эту руку (левую или правую); привязывать можно к камерам и свету; привязка ключуется: предмет лежит на столе до ключа, где его взяли в руку, и отпускается на ключе, где его отпустили.",
		about_x2 = "Ключи костей как в SFM: у выбранного персонажа под ним строки всех костей со своими ключами; у ключа кости может быть своё движение (Stepped, Linear…), даже если на том же кадре ключи других костей; с включёнными ключами костей ключ всего персонажа не трогает кости, у которых свои ключи.",
		about_x3 = "IK: «Вид» → стопы стоят на месте и кисти стоят на месте — отдельные переключатели (двигаете таз — стоят ноги, а если нужно, и руки). Гизмо как в Blender и SFM: кольца вращают по ходу мыши вокруг центра (без рывков, когда кольцо видно ребром), ось, смотрящая в камеру, двигается за мышью; шаги привязки 10 ед., 30°, 0.1 и «Вид» → «Привязка» → «Шагами всегда» (Ctrl — свободно).",
		about_x4 = "«Вид» → «Снять пределы слайдеров» (как flex unlocker в SFM): слайдеры лица, света и камеры заходят за края, например лицо на 2.5 или -1. Надетые головы, маски и одежда с лицевыми слайдерами повторяют лицо носителя и настраиваются сами. Липсинк наёмников TF2 для анимации (модели HWM) берёт собственные фонемы игры для каждого класса, а их лица больше не кривые в покое (их слайдеры идут от -1 до 1).",
		about_x5 = "Запись геймплея пишет технику: машины и лодки игры, simfphys, Glide, LVS — с колёсами и подвеской. Импорт анимации: «Вперёд, ед./с» для ходьбы на месте. Готовые движения больше не «замораживают» редактор на длинных анимациях (танцы).",
		about_x6 = "Таймлайн: стрелки ← / → шагают по кадрам, под дорожками полоса прокрутки. Дополнительный вьюпорт: своё соотношение сторон (шестерёнка → «Соотношение сторон»). Скрыть кость (правый клик по ней): не видна и не выбирается кликом. Камера в глазах персонажа показывает его тело без головы (камера рядом с персонажем больше не делает его невидимым); камера записанной игры — настоящее первое лицо: своё тело игрока не рисуется, как в игре.",
		about_x7 = "Исправлено: больше нескольких источников света на карте светили сквозь стены — теперь тени дают до 8 источников (предел игры), вкладка «Тени» показывает, сколько без теней; WebM, который игра не может создать, записывается в AVI вместо ошибки.",
		about_y1 = "Дубли от первого лица с оружием перед глазами: вьюмодель (оружие с руками, каждая кость её анимации) пишется вместе с дублем, висит на камере дубля и рисуется в её виде как в игре — со своим полем зрения и никогда не уходит в стену. У каждого оружия своя модель, видимая, пока оно в руках.",
		about_y2 = "Техника в дублях: водитель сидит так, как его сгибает Glide (наклон на мотоцикле, ноги на подножках, руки на руле), а не прямо сквозь мотоцикл; быстрое движение больше не дёргается (ключи дубля ставятся точно на целые кадры); двигатель в дубле — слои двигателя Glide с оборотами и зацикленные звуки аддонов (колёса, ветер) становятся клипами с линией громкости и высоты.",
		about_y3 = "Звук через Web Audio API (как Glide играет двигатели): клипы стартуют точно, громкость, панорама и скорость меняются плавно без щелчков, MP3 и OGG теперь попадают в звук видео, а липсинк измеряет голоса MP3 / OGG сразу. gmfm_webaudio 0 возвращает BASS игры. До 1500 звуковых клипов; очереди оружия EFT для ARC9 пишутся по выстрелу (раньше сливались в один клип как «петля»).",
		about_y4 = "Исправлено: наёмники TF2 (HWM), взятые из Q-меню, были с кривым лицом, и липсинк сохранял его в каждом ключе — такие лица ставятся в покой, и в сохранённых сценах тоже; рамка выделения в списке объектов берёт строки, прокрученные колесом; предмет в руке больше не отскакивает в сторону при каждом касании гизмо на некоторых персонажах; единственная кость пропа (static_prop) выбирает весь проп; рабочая камера внутри персонажа больше не срезает ему голову; гостям сервера в режиме GM:FM больше не повторяется «нет прав».",
		about_y5 = "Из SFM: объёмные тени (AO) видны во вьюпортах во время работы («Вид» → «Объёмные тени во вьюпортах»: через камеры / всегда), и у каждой камеры свои (редактор набора анимаций → камера → «Объёмные тени»: как в сцене, вкл. со своим радиусом и силой, выкл.); камера держит фокус на объекте («Фокус на») — он остаётся резким, куда бы ни двигался, остальное размывается; свет: высота луча отдельно от ширины, любая цветовая температура в кельвинах, шире диапазоны яркости и дальности.",
		about_y6 = "Shift + F4 выходит из редактора, что бы его ни держало (в режиме GM:FM сначала спрашивает). Рендер нельзя оборвать: Esc и консоль не открываются, пока снимается видео или картинка. Сцена без камеры рендерится через рабочую камеру. Звук видео раскодирует все файлы через Web Audio — любой WAV, MP3, OGG. «Очистить сцену» убирает и метки NPC для дубля. Дубли от первого лица: камера в глазах игрока как в игре, а не в качающейся голове модели.",
		about_y7 = "Видео рендерится в разы быстрее, как в SFM: кадр снимается в том же игровом кадре, где пришла сцена, сервер отвечает без ожидания тиков, кадр движка заказывается сразу, эффектам частиц нужно 4 игровых кадра на кадр вместо 8, а эффект на движущемся оружии больше не ждёт 0.2 с на каждом кадре (сцена с 22 эффектами: было 31 с на 48 кадров, стало 13 с). Пока рендерится видео, редактор не рисуется: одно окно показывает последний кадр, прогресс, кадры в секунду и оставшееся время и останавливает рендер (Скрывать редактор во время рендера).",
		about_y8 = "Из SFM: Рендер -> Анимация -> Качество - Черновик, Обычное, Высокое, Финальное сразу задают проходы каждого кадра и уровень JPEG; сглаживание видео тоже берёт свою долю проходов. Файл -> Постер: кадр, который уточняется проход за проходом, виден по ходу и сохраняется в PNG или JPEG; сглаживание сэмплами со сдвигом на долю пикселя, как в SFM, вместо кадра двойного размера.",
		about_y9 = "У таймлайна три редактора SFM - кнопки у его левого края, F2 / F3 / F4. Clip Editor: шоты на киноплёнке с началом и длиной, FX-клипы и звуки в разделах Картинка и Звук. Motion Editor: ключи объектов, выделение времени в зелёном цвете SFM. Graph Editor: кривые выделенного объекта или кости, каналы списком слева (клик показывает или прячет канал, двойной клик - только его) - раньше это было отдельное окно.",
		about_y10 = "Фокус камеры как в SFM: Фокусное расстояние и Диафрагма прямо в редакторе набора анимаций; пока вы их меняете, вьюпорты показывают плоскость фокуса - через камеру всё за ней розовое, а под кадром написано расстояние. Предпросмотр в браузере моделей как в SFM: сетка пола и вкладки Рендер (каркас, модель столкновений, без пола, зафиксировать вид, смотреть в камеру), Анимации, Активности и Скины; выбранный там скин идёт в сцену вместе с моделью. Новый эффект в сцене с анимацией проигрывается от плейхеда до конца (окно Эффекты: Проигрывать в анимации), а не висит замершим в воздухе.",
		about_y11 = "Исправлено (мастерская): на картах с окнами порталов областей (gm_boreas: купол) вьюпорты показывали пустоту и места за пределами карты, когда камера была далеко от тела игрока - игра закрывала эти окна по расстоянию от тела, а не от камеры. Пока редактор открыт, они остаются открытыми, а при закрытии получают обратно свои расстояния из карты.",
		about_y12 = "Дубли из демок, как в HLAE (просили в мастерской): запишите демку через Файл -> Демки -> Записать демку и запустите её через Esc -> Повторы (без консоли) - панель GM:FM сверху записывает то, что она показывает: игроков с оружием, NPC, рэгдоллы, движущиеся пропы, вид камеры и звуки - на любой скорости демки. В игре на той же карте Файл -> Импорт дубля из демки превращает его в сцену: рэгдоллы с ключами вдоль дубля и камера вида, так что свет, камеры и SFM-рендер GM:FM работают поверх матча с любого сервера. gmfm_demo показывает панель; она записывает и живую игру.",
		about_y13 = "Исправлено (мастерская: 65 ГБ оперативной памяти и вылет при рендере с шейдерными аддонами): проверка рендер-таргета могла давать сбой на некоторых компьютерах или из-за состояния рендера, оставленного другим аддоном, и тогда каждые две секунды создавался новый таргет полного размера - игра их никогда не освобождает; теперь таргет заменяется не больше двух раз, а проверка сама отключается там, где ей нельзя верить. Эффекты аддонов в ключах камеры больше не включаются и выключаются на каждом кадре рендера (аддон, который строит свои буферы при включении, строил их каждый кадр). Вид рендера и затенение во вьюпортах меняют размер шагами по 64 пикселя, а не с каждым пикселем перетаскиваемого разделителя.",
		about_y14 = "Свободный кадр больше не показывает меньше, чем 16:9: он имеет форму основного вьюпорта, часто это широкая полоса с таймлайном под ней, и при горизонтальном угле обзора такая полоса срезала верх и низ сцены. Свободный кадр шире 16:9 теперь сохраняет высоту кадра 16:9 и показывает больше по бокам (Hor+, как в играх на широких экранах); по нему идут вьюпорты, рендер, предпросмотр, выбор мышью и рамка камеры. 16:9, более узкие свободные кадры и фиксированные пропорции - как раньше.",
		about_y15 = "Исправлено: видео с «Кадром движка» было размазано вбок в каждом кадре - собственное размытие движения игры (Настройки - Видео) принимало скачок между рабочей камерой и камерой рендера за быстрый поворот; пока редактор открыт, оно выключено (рендер размывает движение сам). Исправлено: при включённом затенении (SSAO) превью и рендер показывали тёмные копии объектов рядом с ними (машина и солдат «нарисованы» на стене) - затенение вьюпортов, посчитанное в другом размере, накладывалось и на проходы рендера.",
